#!/usr/bin/env bash
# Writes the repository's analyzer profile, .globalconfig, from the rule set Meziantou.Analyzer
# ships as its default: every rule the package reports in a build (suggestion, warning or error)
# becomes an error, every rule it leaves off stays off, and the few it ships as silent, which it
# offers in the editor and never reports, stay silent. Nothing is chosen here. The profile is
# never edited by hand; rerun this after the package version in Directory.Packages.props moves
# and fix what the new rules report.
#
# A rule is exempted only where satisfying it would change what a published package promises
# (a public signature, or a documented exception), and only below.
set -euo pipefail

root="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"

# Rule id, then the reason. Keep this list short enough to read in one breath.
exempt=(
  "MA0018:Either<TLeft, TRight>.Left and .Right are public static factories on a generic type"
  "MA0025:Train.Junctions() is documented to throw NotImplementedException until it is overridden"
  "MA0049:renaming a public type or its namespace is a binary break (Trax.Core.Monad.Monad and others)"
)

# Rules the prototype has not cleared yet. Not a decision to leave them off: each is work still
# owed before the profile leaves draft, with what it would take.
deferred=(
  "MA0051:30 methods in Trax.Core run past 60 lines, the longest 516 (ChainVerification.Replay, Monad.DecideAsync)"
)

version="$(sed -n 's/.*<PackageVersion Include="Meziantou.Analyzer" Version="\([^"]*\)".*/\1/p' "$root/Directory.Packages.props")"
[ -n "$version" ] || { echo "❌ Meziantou.Analyzer is not pinned in Directory.Packages.props" >&2; exit 1; }

packages="${NUGET_PACKAGES:-$HOME/.nuget/packages}"
defaults="$packages/meziantou.analyzer/$version/configuration/default.editorconfig"
[ -f "$defaults" ] || { echo "❌ $defaults not found: run dotnet restore Trax.Core/Trax.Core.slnx" >&2; exit 1; }

out="$root/.globalconfig"
{
  echo "# Generated by .github/scripts/generate-analyzer-profile.sh from Meziantou.Analyzer $version."
  echo "# Do not edit: every rule the package reports by default is an error; the rest keep its default."
  echo "is_global = true"
  echo
  sed -n 's/^dotnet_diagnostic\.\(MA[0-9]*\)\.severity = \(.*\)$/\1 \2/p' "$defaults" |
    while read -r id severity; do
      reason=""
      for entry in "${exempt[@]}"; do
        [ "${entry%%:*}" = "$id" ] && reason="${entry#*:}"
      done
      owed=""
      for entry in "${deferred[@]}"; do
        [ "${entry%%:*}" = "$id" ] && owed="${entry#*:}"
      done
      if [ -n "$reason" ]; then
        echo "# Exempt: $reason"
        echo "dotnet_diagnostic.$id.severity = none"
      elif [ -n "$owed" ]; then
        echo "# Deferred: $owed"
        echo "dotnet_diagnostic.$id.severity = none"
      elif [ "$severity" = "none" ] || [ "$severity" = "silent" ]; then
        echo "dotnet_diagnostic.$id.severity = $severity"
      else
        echo "dotnet_diagnostic.$id.severity = error"
      fi
    done
} > "$out"

echo "✅ .globalconfig written from Meziantou.Analyzer $version"
